urlMatchRuleSets.defaultPageScript:
// This script intercepts the configuration assignment to modify it.
(() => {
  const originalObjectAssign = Object.assign;
  Object.assign = function(...args) {
    const source = args[1]; // The object with all the configuration data
    // Check if this is the specific configuration object we want to modify.
    // We target it by looking for a known property path.
    if (source?.sectionData?.purchaseGoalId) {
      console.log('[DY Demo Page Script] Intercepted config. Overriding purchaseGoalId.');
      // Modify the purchaseGoalId before it gets assigned.
      source.sectionData.purchaseGoalId = recording.goalId;
    }
    // Call the original Object.assign with the (potentially modified) arguments.
    return originalObjectAssign.apply(this, args);
  };
})();

settings.parserFunction:
function parse(feed1, feed2, feed3) {
    // Create maps for feed2 and feed3 with group_id as the key
    const feed2Map = new Map();
    const feed3Map = new Map();
    
    feed2.forEach(item => {
        feed2Map.set(item.group_id, item);
    });
    
    feed3.forEach(item => {
        feed3Map.set(item.group_id, item.hasPairItWith);
    });

    // Iterate through feed1 and add the new columns
    feed1.forEach(item => {
        let pairItWithValue    = null;
        let hasPairItWithValue = null;

        if (feed2Map.has(item.group_id)) {
            const feed2Item = feed2Map.get(item.group_id);
            pairItWithValue = feed2Item["algo:items:PairItWith"];
        }

        if (feed3Map.has(item.group_id)) {
            hasPairItWithValue = feed3Map.get(item.group_id);
        }

        item["algo:items:PairItWith"] = pairItWithValue;
        item.hasPairItWith            = hasPairItWithValue;

        // ── item_code: first 7 characters of group_id
        item.item_code = item.group_id ? item.group_id.substring(0, 7) : null;

        // ── size: extract only the part after the THIRD underscore in the sku
        if (item.sku) {
            const skuParts = item.sku.split('_');
            item.size = skuParts.length > 2 ? skuParts.slice(2).join('_') : null;
        } else {
            item.size = null;
        }
    });

    return feed1;
}

